__attribute__((noinline)) static uint64_t strat_0(double price, double *ewma) {
    *ewma += (price - *ewma) / 8.0;          /* same base work as the Python strategy */
    uint64_t x = (uint64_t)price;

    return (price > *ewma ? 2 : 1) + (x & 0);  /* "submit_trade" */
}
